<?php require_once __DIR__.'/config.php'; if(!isset($pdo)){?><script>location.href='setup.php'</script><?php exit;} $q=trim($_GET['q']??'');$sql='SELECT * FROM movies';$params=[];if($q!==''){$sql.=' WHERE title LIKE ? OR genre LIKE ? OR country LIKE ?';$like="%$q%";$params=[$like,$like,$like];}$sql.=' ORDER BY featured DESC,trending DESC,created_at DESC';$st=$pdo->prepare($sql);$st->execute($params);$movies=$st->fetchAll();$hero=$movies[0]??null;$trending=array_slice($movies,0,12);$genres=[];foreach($movies as $m)$genres[$m['genre']??'Other'][]=$m;?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>AfrikaFlix — African Movies</title><meta name="description" content="AfrikaFlix — a modern African movie streaming platform"><link rel="stylesheet" href="assets/movie.css"></head><body><?php include __DIR__.'/partials/movie-nav.php';?><?php if($hero):?><section class="hero" style="background-image:linear-gradient(90deg,#000 0%,rgba(0,0,0,.82) 30%,rgba(0,0,0,.18) 75%,#000 100%),linear-gradient(0deg,#070707 0%,transparent 35%),url('<?=e($hero['backdrop_url']?:$hero['poster_url'])?>')"><div class="hero-content"><div class="eyebrow">AFRIKAFLIX ORIGINAL · <?=e($hero['country'])?></div><h1><?=e($hero['title'])?></h1><p><?=e($hero['description'])?></p><div class="buttons"><a class="btn primary" href="watch.php?id=<?=$hero['id']?>">▶ Watch now</a><a class="btn secondary" href="watch.php?id=<?=$hero['id']?>">ⓘ More info</a></div></div></section><?php endif;?><main class="content"><section class="section"><div class="section-head"><h2>🔥 Trending now</h2><a href="?q=">View all</a></div><div class="row"><?php foreach($trending as $m):?><a class="card" href="watch.php?id=<?=$m['id']?>"><img loading="lazy" src="<?=e($m['poster_url'])?>" alt="<?=e($m['title'])?>"><span class="badge">TOP</span><div class="card-info"><div class="card-title"><?=e($m['title'])?></div><div class="meta"><?=e($m['year'])?> · <?=e($m['genre'])?> · <?=e($m['country'])?></div></div></a><?php endforeach;?></div></section><?php foreach($genres as $genre=>$items):?><section class="section"><div class="section-head"><h2><?=e($genre)?></h2></div><div class="row"><?php foreach(array_slice($items,0,6) as $m):?><a class="card" href="watch.php?id=<?=$m['id']?>"><img loading="lazy" src="<?=e($m['poster_url'])?>" alt="<?=e($m['title'])?>"><div class="card-info"><div class="card-title"><?=e($m['title'])?></div><div class="meta"><?=e($m['year'])?> · <?=e($m['country'])?></div></div></a><?php endforeach;?></div></section><?php endforeach;?></main><footer class="footer">© <?=date('Y')?> AfrikaFlix · Stream African stories. Only upload and distribute movies you have the rights to use.</footer></body></html>